mapper.update:
UPDATE pharmacy_in_item
seq_no = #{seqNo}, drug_name = #{drugName}, spec = #{spec}, manufacturer = #{manufacturer}, quantity = #{quantity}, unit_price = #{unitPrice}, total_amount = #{totalAmount}, batch_no = #{batchNo}, expire_date = #{expireDate}, item_remark = #{itemRemark},
WHERE id = #{id}

mapper.select:
SELECT COALESCE(SUM(total_amount), 0)
FROM pharmacy_in_item
WHERE pharmacy_id = #{orderId}
